  "discovery.coverage.unknowns": "Bekannte blinde Flecken",
  "discovery.coverage.unknownsHeading": "Was diese Installation nicht sehen kann",
  "discovery.coverage.segment": "Segment",
  "discovery.coverage.lastSwept": "Zuletzt erfasst",
  "discovery.coverage.never": "Nie",
  "discovery.coverage.segmentsCaption": "Deklarierte Netzsegmente und die Aktualität ihrer Erfassung",
  "discovery.coverage.help":
    "Die Abdeckung wird an den von Ihnen deklarierten Segmenten gemessen, nicht an dem, was die Erkennung zufällig gefunden hat — ein Bestand, der nur aus Funden aufgebaut ist, kann beschreiben, was er gefunden hat, und sonst nichts. Ausgeschlossene Segmente bleiben in beiden Hälften unberücksichtigt, statt als abgedeckt zu zählen. Ein Zertifikat ohne Beobachtung dahinter ist ein Beleg für eine Ausstellung, nicht für eine Bereitstellung.",
  "operations.jobs.receipts.verified": "Verifizierte Quittungen",
  "operations.jobs.receipts.rejected": "Abgelehnte Quittungen",
  "operations.jobs.receipts.lastRejected": "Jüngste Ablehnung",
  "operations.jobs.receipts.none": "Keine",
  "operations.jobs.receipts.help":
    "Jeder abschließende Bericht wird vom Agenten mit dem Schlüssel signiert, der hinter seinem Kanalzertifikat steht. Damit ist die Aufzeichnung dessen, was ein Agent getan hat, ein Nachweis, den diese Steuerungsebene nicht selbst hätte erzeugen können. Eine Ablehnung bedeutet, dass ein Agent glaubt, Arbeit geleistet zu haben, die dieses Verzeichnis nicht festhalten wird — entweder ist seine Uhr abgewichen, oder seine Signatur stammt nicht von dem Zertifikat, mit dem er sich verbunden hat.",
  "operations.jobs.heading": "Agent-Auftragsregister",
  "operations.jobs.inFlight": "Von einem Agenten gehalten",
  "operations.jobs.kind": "Auftragsart",
  "operations.jobs.noneEnabled":
    "Es ist keine Auftragsart aktiviert, daher wird den Agenten nichts \u00fcbergeben. Eine Art wird \u00fcbernehmbar, wenn ihr Executor ausgeliefert wird und Sie sie in agent_channel.claimable_job_kinds aktivieren.",
  "operations.jobs.notServed":
    "Der Agentenkanal ist nicht eingebunden, daher gibt es kein Auftragsregister anzuzeigen. Aktivieren Sie agent_channel, damit Agenten Arbeit \u00fcbernehmen k\u00f6nnen.",
  "operations.jobs.oldest": "L\u00e4ngste Wartezeit",
  "operations.jobs.waiting": "Wartend",
  "operations.status.queued": "Eingereiht",
  "certificates.ingest.pem.label": "Zertifikat einfügen",
  "certificates.ingest.pem.description": "Nur öffentliches Zertifikats-PEM — private Schlüssel gehören niemals in dieses Formular.",
  "certificates.ingest.placement.label": "Verantwortung zuweisen",
  "certificates.ingest.placement.description": "Verantwortliche Eigentümer wählen und festhalten, wo das Zertifikat ausgerollt ist.",
  "certificates.ingest.review.label": "Prüfen und aufnehmen",
