  "policy.overview.description":
    "Ausstellungs-, Ausroll- und Widerrufsmutationen durchlaufen das OPA/Rego-Default-Deny-Gate, RA-Trennung, Vier-Augen-Freigabe und Bound-Profile-Prüfungen, bevor Zustandsänderungen emittiert werden.",
  "policy.enforcement.heading": "Durchsetzungspfad",
  "policy.enforcement.description":
    "Der Browser sendet keine Tenant-ID und umgeht keine Richtlinie. Er bittet den Lifecycle-Workflow um die Mutation; das Backend wertet die Richtlinie aus und emittiert entweder das Ereignis oder liefert ein fail-closed Problem.",
  "policy.enforcement.auditPrefix":
    "Entscheidungen sind Evidenzereignisse. Nutzen Sie Audit, um Allow-, Deny- und Auswertungsfehler-Einträge mit Akteur, Ressource, Hash und Payload aus dem Ereignisstrom zu inspizieren. Aktionsfehler erscheinen weiterhin dort, wo der Operator den Workflow gestartet hat, auf",
