  "source.workload.api.serving.b3wla0008": "Lokal bereitgestellt",
  "source.workload.api.unreported.b3wla0009": "Nicht gemeldet",
  "source.workload.api.not.serving.b3wla0010": "Nicht bereitgestellt",
  "source.svids.since.start.b3wla0011": "{value1} seit Agentenstart",
  "source.never.b3wla0012": "Nie",
  "source.endpoint.key.custody.b2cus00001": "Schl\u00fcsselverwahrung je Ziel",
  "source.endpoint.key.custody.help.b2cus00002":
    "F\u00fcr jedes Bereitstellungsziel: welcher Prozess den privaten Schl\u00fcssel erzeugt. Ein Ziel mit executor=agent erzeugt seinen Schl\u00fcssel auf dem Host, der ihn ausliefert, und diese Steuerebene sendet dorthin kein Schl\u00fcsselmaterial. Alle anderen Ziele nutzen den Weg \u00fcber die Steuerebene, der funktioniert \u2014 das ist die verbleibende Migration, kein Fehler.",
  "source.endpoint.key.custody.summary.b2cus00003": "{value1} von {value2} Zielen erzeugen Schl\u00fcssel auf dem Host ({value3}%).",
  "source.endpoint.key.custody.caption.b2cus00004": "Bereitstellungsziele und wo ihre privaten Schl\u00fcssel erzeugt werden",
  "source.target.b2cus00005": "Ziel",
