  "source.disabled.b2cus00011": "Deaktiviert",
  "source.endpoint.verification.d2ver00001": "Endpoint-Verifizierung",
  "source.endpoint.verification.help.d2ver00002":
    "Jede Zeile ist ein TLS-Handshake, den jemand tats\u00e4chlich durchgef\u00fchrt hat, kein Protokoll dessen, was diese Control Plane getan hat. Eine Erneuerung kann bei der CA gelingen, von einem Konnektor ausgeliefert werden und den Listener nie erreichen \u2013 w\u00e4hrend jede Zustellquittung gr\u00fcn bleibt und Clients weiterhin das alte Zertifikat erhalten.",
  "source.endpoint.verification.caption.d2ver00003": "Beobachtete Endpoint-Identit\u00e4t nach Beobachtungspunkt",
