  "source.start.with.a.profile.bound.request.or.conn.19cdbff548":
    "Beginnen Sie mit einer profilgebundenen Anfrage oder verbinden Sie einen Aussteller, bevor das erste Zertifikat ausgestellt wird.",
  "source.state.a3b50c4767": "Zustand",
  "source.agent.role.a2r0le0001": "Rolle",
  "source.agent.role.help.a2r0le0002":
    "Wo dieser Agent läuft, bestimmt, welche Arbeit er erhält. Die Rolle wird in das Zertifikat eingeprägt, mit dem er sich registriert, und kann ohne erneute Registrierung nicht geändert werden.",
  "source.agent.role.host.a2r0le0003": "Host",
  "source.agent.role.host.help.a2r0le0004":
    "Wirkt auf dem Rechner, auf dem er läuft: erfasst die Anmeldeinformationen dieses Hosts und stellt für dessen Dienste bereit.",
  "source.agent.role.network.a2r0le0005": "Netzwerk-Relais",
  "source.agent.role.network.help.a2r0le0006":
    "Wirkt auf Geräte in seinem Segment, die selbst keinen Agenten ausführen können — Load Balancer, Appliances, Cloud-Zertifikatspeicher — und prüft Endpunkte aus Sicht eines Clients.",
  "source.agent.role.relay.warning.a2r0le0007":
    "Ein Relais hält die Anmeldeinformationen der Geräte, für die es einsteht. Die Vergabe dieser Rolle erfordert die Berechtigung agents:relay.grant.",
  "source.agent.role.empty.a2r0le0008": "Keine Rolle ausgewählt. Der registrierte Agent ist reiner Host-Agent — der Standard für einen Agenten ohne Zuweisung.",
  "source.agent.role.unreported.a2r0le0009": "Noch nicht gemeldet",
  "source.agent.role.source.a2r0le0010": "Aus dem zuletzt vorgelegten Zertifikat dieses Agenten gelesen. Eine Rollenänderung ist eine erneute Registrierung.",
  "source.executes.on.a3vant0001": "Ausführung auf",
  "source.vantage.host.a3vant0002": "Host-Agent",
  "source.vantage.relay.a3vant0003": "Netzwerk-Relais",
  "source.vantage.control.plane.a3vant0004": "Steuerungsebene",
  "source.relay.executes.a3rel0001": "Relais führt aus",
  "source.relay.none.a3rel0002": "Dieser Build enthält keinen Relais-Executor.",
  "source.relay.flags.a3rel0003": "Benötigt Flag:",
  "source.relay.help.a3rel0004":
    "Was der Agenten-Build dieses Servers als Relais ausführen kann. Ein Agent fordert diese Arbeit nur mit der Netzwerkrolle in seinem Zertifikat an und löst jede Anmeldeinformation für genau einen Versuch ein.",
  "source.dry.run.queued.d5dry00001": "Probelauf in Warteschlange (noch kein Ergebnis)",
  "source.dry.run.planned.d5dry00002": "Bereitstellung würde gelingen (nichts geändert)",
  "source.dry.run.blocked.d5dry00003": "Bereitstellung würde fehlschlagen (nichts geändert)",
  "source.adcs.heading.f1adcs0001": "AD CS-Zertifikatvorlagen",
  "source.adcs.description.f1adcs0002":
    "Vorlagen legen fest, was eine Windows-PKI ausstellen darf. Ein Netzwerk-Relais in der Domäne liest jede Vorlage, ihre veröffentlichenden CAs und die SIDs mit Registrierungsrechten.",
  "source.adcs.error.f1adcs0004": "AD CS-Vorlagenstatus konnte nicht geladen werden",
  "source.adcs.unobserved.title.f1adcs0005": "Noch hat kein Relais ein Verzeichnis gelesen",
  "source.adcs.unobserved.body.f1adcs0006":
    "Das ist nicht dasselbe wie keine AD CS-Umgebung. Erstellen Sie eine AD CS-Ermittlungsquelle und einen Zeitplan für einen Agenten mit Netzwerkrolle in der Domäne; die Steuerungsebene liest das Verzeichnis niemals selbst.",
  "source.adcs.critical.f1adcs0007": "Kritische Vorlagen",
