  "source.custody.key.b5cust0001": "Schlüsselverwahrung",
  "source.custody.unrecorded.b5cust0002":
    "Dieser Datensatz belegt nicht, wo der private Schlüssel erstellt wurde oder wie er geschützt wird. Ein Grund für die fehlenden Nachweise ist nicht erfasst. Nicht erfasst bedeutet nicht sicher.",
  "source.status.920e413c7d": "Status",
