  "source.test.532eaabd95": "Test",
  "source.the.agent.row.remains.as.an.offboarded.tom.42a25faa10":
    "Die Agentenzeile bleibt als stillgelegter Tombstone-Datensatz erhalten, und zukünftige mTLS-RPCs dieses Agenten werden abgelehnt.",
  "source.the.browser.never.chooses.a.tenant.id.thro.091c4e9bb3":
    "Der Browser wählt niemals eine Tenant-ID über eine Route, eine Abfragezeichenfolge oder ein Formularfeld aus. Die Backend-Sitzung oder das API-Token stellt sie bereit, und PostgreSQL RLS setzt sie unterhalb der API durch.",
  "source.the.cbom.scanner.inventories.algorithms.ke.94de5272b7":
    "Der CBOM-Scanner inventarisiert Algorithmen, Schlüsselgrößen, TLS-Versionen und schwache Kryptolage. Die Richtlinienuntergrenze ist RSA-2048, EC-256 und TLS 1.2; 3DES/DES/RC4/NULL/EXPORT/MD5 sind verboten.",
  "source.the.console.could.not.read.runtime.status.a01258a71d":
    "Die Konsole konnte den Laufzeitstatus nicht lesen und zeigt daher die sichere Baseline: Ohne bestätigtes Modell gibt es keinen bestätigten Prompt-Datenabfluss.",
  "source.the.console.is.currently.loaded.over.an.en.4e9bab4e91": "Die Konsole wird derzeit über eine verschlüsselte Browserverbindung geladen.",
  "source.the.console.reads.projected.connector.deli.091ecd8115":
    "Die Konsole liest projizierte Connector-Auslieferungsnachweise und Lebenszyklus-Rotationsläufe. Dies sind auditgeeignete Routing-Datensätze: Es werden weder private Zertifikatsschlüssel noch Secret-Werte zurückgegeben.",
  "source.the.local.vite.preview.is.http.production.7f2e105c44":
    "Die lokale Vite-Vorschau verwendet HTTP. In der Produktion sollte HTTPS verwendet oder mTLS terminiert werden, bevor Operatoren sie nutzen.",
  "source.the.native.store.returns.names.and.version.6f88143feb":
    "Der native Store gibt nur Namen und Versionen zurück. Beim Erstellen und Rotieren wird ein Wert einmal gesendet; anschließend verwirft diese Seite die Eingabe und zeigt Metadaten an.",
  "source.the.register.checks.the.same.origin.protoc.851c152de8":
    "Das Register prüft die von der Control Plane bereitgestellten Same-Origin-Pfade der Protokoll-Responder. Ein Protokoll wird nur als deaktiviert angezeigt, wenn sein Responder-Pfad fehlt oder nicht verfügbar ist.",
  "source.this.json.is.sent.to.the.profile.workflow.37a80f1c5b":
    "Dieses exakte JSON wird als versioniertes Ausstellungsprofil gespeichert. Der Server prüft es, bevor die Regel etwas ausstellen kann.",
  "source.this.plaintext.was.decoded.locally.from.th.fbd3275222":
    "Dieser Klartext wurde lokal aus der Transit-Antwort decodiert. Durch Schließen wird er von der Seite entfernt.",
  "source.this.submits.a.single.bulk.revocation.requ.ab3df219e2": "Dies sendet eine einzige Sammelwiderrufsanfrage für die",
  "source.this.submits.one.bulk.revocation.request.f.f1809ceaf2": "Dies sendet eine Sammelwiderrufsanfrage für alle",
  "dashboard.empty.description":
    "Dieser Tenant hat noch keine Credentials. Der Leitfaden mit sechs Bildschirmen prüft die Signierung, aktiviert die Evaluierungsprotokolle, stellt das erste Zertifikat aus und bietet optionale Integrations- und Agentenschritte — etwa zehn Minuten. Möchten Sie sich zuerst umsehen? Erkunden Sie die Konsole.",
  "certificates.readiness.current": "Aktueller Stand",
  "certificates.readiness.200DayModel": "200-Tage-Modell",
  "certificates.readiness.100DayModel": "100-Tage-Modell",
  "certificates.readiness.47DayTarget": "47-Tage-Ziel",
  "source.this.value.is.the.exact.once.redeem.result.ed19b63953":
    "Dieser Wert ist das Ergebnis der genau einmal erlaubten Einlösung. Eine zweite Einlösung muss fehlschlagen.",
  "source.this.view.shows.issuer.name.kind.public.ke.5166a2828e":
    "Diese Ansicht zeigt Name und Art des Ausstellers, den öffentlichen Schlüssel, die Verwahrungsgrenze und die Kettenmetadaten. Die darunterliegenden Bereiche für Zeremonie und verwaltete Schlüssel steuern die zugehörigen geschützten Workflows.",
