  "source.transit.operations.keep.key.material.serve.be62c8b11a":
    "Transit-Operationen halten das Schlüsselmaterial auf dem Server. Diese Seite codiert lokalen Klartext für die API mit base64, löscht Klartexteingaben nach dem Verschlüsseln und zeigt entschlüsselte Werte nur in einem Anzeigefeld an.",
