  "posture.pqcMigration.heading": "PQC-Migrationsablauf",
  "posture.pqcMigration.description":
    "Wählen Sie gefährdete CBOM-Assets, prüfen Sie den exakten Plan und autorisieren Sie anschließend ausdrücklich eine rollback-sichere Migration.",
  "posture.pqcMigration.checkingEdition": "PQC-Migrationsberechtigung wird geprüft...",
  "posture.pqcMigration.unavailableHeading": "Migrationsausführung ist in dieser Edition nicht verfügbar",
  "posture.pqcMigration.communityBody":
    "Community hält CBOM-Erkennung und Bereitschaft vollständig nutzbar. Die lizenzierte Flotten-Migrationsengine ist nicht eingebunden; diese Seite ruft daher keine Migrations-API auf.",
  "posture.pqcMigration.readOnlyBody":
    "Die Lizenz ist schreibgeschützt. Vorhandene CBOM-Nachweise bleiben sichtbar, neue Pläne, Läufe und Rollbacks sind deaktiviert.",
